// Render docs/FIELDS.md from the canonical schema — the human-readable field
// reference. Regenerated by the codegen workflow; do not edit by hand.
import { readFileSync, writeFileSync } from "node:fs";
const root = new URL("..", import.meta.url);
const SCHEMA = "schema/waterx-config.schema.json";
const OUT = "docs/FIELDS.md";
const schema = JSON.parse(readFileSync(new URL(SCHEMA, root), "utf8"));
const lines = ["# waterx-config field reference", "",
  `> Generated from [\`${SCHEMA}\`](../${SCHEMA}) by \`scripts/gen-fields-doc.mjs\` — do not edit by hand.`, ""];
const typ = (s) => {
  if (!s || typeof s !== "object") return "any";
  if (s.$ref) return s.$ref.split("/").pop();
  if (s.enum) return s.enum.map((e) => JSON.stringify(e)).join(" \\| ");
  if (s.type === "object" && s.additionalProperties && typeof s.additionalProperties === "object")
    return `map<string, ${typ(s.additionalProperties)}>`;
  if (s.type === "object") return "object";
  if (s.type === "array") return `array<${typ(s.items)}>`;
  return Array.isArray(s.type) ? s.type.join("\\|") : (s.type ?? "any");
};
const esc = (x) => String(x ?? "").replace(/\|/g, "\\|").replace(/\n/g, " ");
lines.push("## Top level", "", "| field | type | notes |", "|---|---|---|");
for (const [k, s] of Object.entries(schema.properties)) {
  if (k === "packages") continue;
  lines.push(`| \`${k}\` | ${typ(s)} | ${esc(s.description ?? "")} |`);
}
lines.push("", "## Packages", "",
  "Every package carries the same identity block (the map is uniform — new packages need no schema change):", "");
propsTable(schema.properties.packages.additionalProperties);
/** Render one node's properties as the standard 4-column table. */
function propsTable(node) {
  lines.push("| field | type | required | notes |", "|---|---|---|---|");
  const req = new Set(node.required ?? []);
  for (const [k, s] of Object.entries(node.properties ?? {})) {
    lines.push(`| \`${k}\` | ${typ(s)} | ${req.has(k) ? "✓" : ""} | ${esc(s.description ?? "")} |`);
  }
  lines.push("");
}

// The domain trees are the document's substance — render each domain/rule as
// its own section, same shape as Packages.
for (const section of ["objects", "oracle_rules"]) {
  const ss = schema.properties[section];
  if (!ss?.properties) continue;
  lines.push("", `## ${section}`, "");
  for (const [domain, ds] of Object.entries(ss.properties)) {
    lines.push(`### \`${section}.${domain}\``, "");
    propsTable(ds);
    for (const [field, fs] of Object.entries(ds.properties ?? {})) {
      const item = fs?.additionalProperties;
      if (item && typeof item === "object" && item.properties) {
        lines.push(`#### \`${section}.${domain}.${field}\` — each entry`, "");
        propsTable(item);
      }
    }
  }
}

lines.push("## Shared definitions", "", "| def | pattern | meaning |", "|---|---|---|");
for (const [k, s] of Object.entries(schema.$defs ?? {}))
  lines.push(`| \`${k}\` | \`${esc(s.pattern ?? "")}\` | ${esc(s.description ?? "")} |`);
writeFileSync(new URL(OUT, root), lines.join("\n") + "\n");
console.log(`${OUT} written`);
